using System;using UnityEngine;
namespace Veilbound {public partial class VeilGame {
 public static double CityTimeMultiplier(int tier){int[] t={1,10,20,30,40,60,80,90,100};double[] m={2,3,3.8,4.5,5,5.8,6.5,6.8,7};if(tier<=1)return 2;for(int i=1;i<t.Length;i++)if(tier<=t[i])return m[i-1]+(m[i]-m[i-1])*(tier-t[i-1])/(t[i]-t[i-1]);return 7+.02*(tier-100);}
 void CityServiceDetails(string id){if(id=="enchanter"){CityMysticDetails();return;}if(id=="library"){CityLibraryDetails();return;}if(id=="clothier"){CityMaterialServiceDetails();return;}bool cloth=id=="clothier";GUI.Label(new Rect(1100,385,450,115),cloth?"Clothier progression: 10 workshop levels. The existing cloth, cape and leather recipes share this workshop. Additional material recipes are still being designed.":id=="library"?"Library plot reserved. Its construction uses starter wood, stone, textiles, hides and tin bars. Research projects and their final costs are the next implementation stage.":"Plot reserved. This service will be unlocked through Library research. Its gameplay system is still in development.",CityType(17,cityIvory));if(cloth){CityButton(1100,530,450,44,"Craft cloth and capes",()=>OpenCityWorkshop(true,1),city.clothier>0);CityButton(1100,590,450,44,"Craft hide and leather armour",()=>OpenCityWorkshop(true,2),city.clothier>0);CityButton(1100,650,450,40,"Manage textiles",()=>SelectCityBuilding("weaver"));CityButton(1100,710,450,40,"Manage hunting",()=>SelectCityBuilding("hunters"));}else GUI.Label(new Rect(1100,570,450,100),"SERVICE IN DEVELOPMENT\nThe map shows its planned position and appearance.",CityType(17,muted));}
}}
